53	const PROCESSING_FEE = 5;
54	
55	const BASE_PREMIUMS: Record<string, number> = {
56	  sword: 100,
57	  amulet: 60,
58	  staff: 80,
59	  potion: 40,
60	  rune: 25,
61	  moonstone: 25,
62	};
63	
64	const COMPONENT_TYPES = ["rune", "moonstone"];
65	const COMPONENT_BLOCK_SIZE = 3;
66	const COMPONENT_BLOCK_PREMIUM = 60;
67	
68	const CURSE_SURCHARGE_PERCENT = 50;
69	const HIGH_ENCHANTMENT_THRESHOLD = 5;
70	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
71	
72	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
73	const LOYALTY_DISCOUNT_PERCENT = 20;
74	const LOYALTY_MINIMUM_YEARS = 2;
75	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = 15;
76	
77	// Integer multiply before divide keeps fractional percentages exact
78	// (e.g. 10% of 25 is exactly 2.5 — no float noise from multiplying by 1.1).
79	const percentOf = (amount: number, percent: number): number =>
80	  (amount * percent) / 100;
81	
82	const isComponent = (item: QuoteItem): boolean =>
83	  COMPONENT_TYPES.includes(item.type);
84	
85	const basePremiumOf = (type: string): number => {
86	  const premium = BASE_PREMIUMS[type];
87	  if (premium === undefined) {
88	    throw new Error(`unknown item type: ${type}`);
89	  }
90	  return premium;
91	};
92	
93	const sumBy = <T>(values: T[], amount: (value: T) => number): number =>
94	  values.reduce((sum, value) => sum + amount(value), 0);
95	
96	const isCursed = (item: QuoteItem): boolean => item.cursed === true;
97	
98	const isHighlyEnchanted = (item: QuoteItem): boolean =>
99	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
100	
101	// Item surcharge: a fixed percent of each qualifying item's base premium.
102	const itemSurcharge = (
103	  items: QuoteItem[],
104	  applies: (item: QuoteItem) => boolean,
105	  percent: number
106	): number =>
107	  sumBy(items.filter(applies), (item) =>
108	    percentOf(basePremiumOf(item.type), percent)
109	  );
110	
111	// Pricing rule: a block of exactly 3 alike components costs a flat block premium.
112	const componentTypePremium = (items: QuoteItem[], type: string): number => {
113	  const count = items.filter((item) => item.type === type).length;
114	  return count === COMPONENT_BLOCK_SIZE
115	    ? COMPONENT_BLOCK_PREMIUM
116	    : count * basePremiumOf(type);
117	};
118	
119	const quotePremium = (
120	  items: QuoteItem[],
121	  customer: Customer,
122	  isFollowUpContract: boolean
123	): number => {
124	  const componentsPremium = sumBy(COMPONENT_TYPES, (type) =>
125	    componentTypePremium(items, type)
126	  );
127	  const mainItemsPremium = sumBy(
128	    items.filter((item) => !isComponent(item)),
129	    (item) => basePremiumOf(item.type)
130	  );
131	  const policyBasePremium = componentsPremium + mainItemsPremium;
132	  const curseSurcharge = itemSurcharge(items, isCursed, CURSE_SURCHARGE_PERCENT);
133	  const enchantmentSurcharge = itemSurcharge(
134	    items,
135	    isHighlyEnchanted,
136	    HIGH_ENCHANTMENT_SURCHARGE_PERCENT
137	  );
138	  // Policy-wide modifiers are all computed on the unmodified policy base.
139	  const firstInsuranceSurcharge = percentOf(
140	    policyBasePremium,
141	    FIRST_INSURANCE_SURCHARGE_PERCENT
142	  );
143	  const loyaltyDiscount =
144	    customer.yearsWithMHPCO >= LOYALTY_MINIMUM_YEARS
145	      ? percentOf(policyBasePremium, LOYALTY_DISCOUNT_PERCENT)
146	      : 0;
147	  const followUpContractDiscount = isFollowUpContract
148	    ? percentOf(policyBasePremium, FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT)
149	    : 0;
150	  return Math.ceil(
151	    policyBasePremium +
152	      curseSurcharge +
153	      enchantmentSurcharge +
154	      firstInsuranceSurcharge -
155	      loyaltyDiscount -
156	      followUpContractDiscount +
157	      PROCESSING_FEE
158	  );
159	};
160	
161	const INSURANCE_VALUES: Record<string, number> = {
162	  sword: 1000,
163	  amulet: 600,
164	  rune: 250,
165	};
166	
167	const DEDUCTIBLE = 100;
168	const CAP_MULTIPLIER = 2; // payout cap is twice the policy's insurance sum
169	
170	const insuranceSumOf = (items: QuoteItem[]): number =>
171	  sumBy(items, (item) => INSURANCE_VALUES[item.type]);
172	
173	// Claim clause: items enchanted at or above this level are only reimbursed
174	// at 50%. Distinct rule from the premium's HIGH_ENCHANTMENT_THRESHOLD (5).
175	const CLAIM_HALVING_ENCHANTMENT_THRESHOLD = 8;
176	const HALVED_REIMBURSEMENT_PERCENT = 50;
177	
178	const reimbursementFor = (
179	  policyItems: QuoteItem[],
180	  damage: Damage
181	): number => {
182	  const insuredItem = policyItems.find(
183	    (item) => item.type === damage.itemType
184	  );
185	  if (insuredItem === undefined) {
186	    throw new Error(`damaged item not covered by policy: ${damage.itemType}`);
187	  }
188	  return (insuredItem.enchantment ?? 0) >= CLAIM_HALVING_ENCHANTMENT_THRESHOLD
189	    ? percentOf(damage.amount, HALVED_REIMBURSEMENT_PERCENT)
190	    : damage.amount;
191	};
192	
193	// A policy is what a quote step creates: the insured items plus the payout
194	// cap that later claims against this policy draw down.
195	interface Policy {
196	  items: QuoteItem[];
197	  remainingCap: number;
198	}
199	
200	const openPolicy = (items: QuoteItem[]): Policy => ({
201	  items,
202	  remainingCap: CAP_MULTIPLIER * insuranceSumOf(items),
203	});
204	
205	const settleClaim = (policy: Policy, damages: Damage[]): ClaimResult => {
206	  // Payouts round down in MHPCO's favor — mirrors the Math.ceil on premiums.
207	  const uncappedPayout = Math.floor(
208	    sumBy(damages, (damage) => reimbursementFor(policy.items, damage) - DEDUCTIBLE)
209	  );
210	  const payout = Math.min(uncappedPayout, policy.remainingCap);
211	  return { payout, remainingCap: policy.remainingCap - payout };
212	};
213	
214	export const runScenario = (scenario: Scenario): ScenarioResult => {
215	  // Indexed by step index — claim steps reference their policy that way.
216	  const policies: Policy[] = [];
217	  const results = scenario.steps.map((step, index): StepResult => {
218	    if (step.op === "quote") {
219	      policies[index] = openPolicy(step.items);
220	      return {
221	        premium: quotePremium(step.items, scenario.customer, index > 0),
222	      };
223	    }
224	    const policy = policies[step.policy];
225	    const result = settleClaim(policy, step.incident.damages);
226	    policy.remainingCap = result.remainingCap;
227	    return result;
228	  });
229	  return { results };
230	};
